## S11_Coding.docx. Coding, statistics and supplemental graphs for the real-world data confidence interval widths in Figure 4.## Title of article: Triplication: an important component of the modern scientific method.## Authors:  Jeremy S.C. Clark, Karina Szczypiór-Piasecka, Kamila Rydzewska, Konrad Podsiadło.## INSTRUCTIONS: (1) choose mypath; (2) Sections 4-7 require four passes: TYPE <- "NOsys" or "SYS", each with grW <- TRUE or FALSE (Welch-Satterthwaite adjustment): choose one combination per run; (3) copy all code into R and run. (Section 3 gives both Welch and non-Welch columns in a single run; k is the number of replicates included in an analysis).mypath <- "/Users/jsc/Documents/aaJ Clark MACBOOK 2026 PUM/9991 SUBMITTED R3/"grW <- FALSE ## if TRUE gives Welch-Satterthwaite adjustment.TYPE <- "SYS"   ## "NOsys" (no systematic error inclusion)  or "SYS" (systematic error inclusion).## Sections:## R Libraries.## Section 1. Original data: extracted from Supplemental file S8. Table S11.T1.## Section 2.1. Combining p-values; triple-result joint probability and Fisher's method. Imaginary examples. Table S11.T2.## Section 2.2. Greenwood statistic normalized: Gw, for imaginary example Table S11.T3.## Section 2.3. Normalized Greenwood calculations for real-world data. TABLE S11.T4. ## Section 3. Confidence interval widths, actual and expected. TABLE S11.T5.## Section 4. Generalized additive model (GAM) fits.## Section 4.1. GAM fits: NOsys results - no Welch-Satterthwaite adjustment.## Section 4.2. GAM fits: NOsys results - with Welch-Satterthwaite adjustment.## Section 5.1. GAM fits: SYS results - no Welch-Satterthwaite adjustment.## Section 5.2. GAM fits: SYS results - with Welch-Satterthwaite adjustment.## Section 6. NOsys GAM graphs.## Section 7. SYS GAM graphs.## Section 8. Do points lie within 25% of the expected decreasing curve ?## Section 8.1. NOsys data within 25% band. TABLEs S11.T6, S11.T7.## Section 8.2. SYS data within 25% band. TABLEs S11.T8, S11.T9.## For coding references see Supplemental_file_S7.##________________________________________________________## R Libraries:ipak <- function(pkg){ new.pkg <- pkg[!(pkg %in% installed.packages()[, "Package"])]if (length(new.pkg))     install.packages(new.pkg, dependencies = TRUE, repos="http://cran.r-project.org")sapply(pkg, require, character.only = TRUE)} ## end functionpackages <- c("COINr", "dplyr", "tidyr", "mgcv", "ggplot2", "purrr") ipak(packages) ## References given at end of document.## Section 1. Original data: extracted from Supplemental file S8, but more details concerning extraction are given in S7 section 12.1.## TABLE S11.T1 (dataframe original_data). Original data to which columns are added later after analyses.## column definitions:## study = study from articles: Tonk_A: from Tonk et al. (2017). Kichigina_B from  Kichigina et al. (2017). Carlucci_C from Carlucci et al. (2017). Lawrence_D from Lawrence et al. (2017). Zhang_E from Zhang et al. (2017). Driver_F from Driver et al. (2017). Zhou_G from Zhou et al. (2017). Clark_H from unpublished data from a study preliminary to Clark et al. (1993). For references, see main article.## level = level as found in original article ## k = order of level as in original article (also number of replicates included in an analysis)## mean = mean from original article## SD = standard deviation from original article, if given, or## SE_ori = standard error from original article, if given ## (NOTE: either SD or SE_ori are used in articles to describe the same type of variance !)## N = number of samples for that leveloriginal_data <- ("study    	level		k		mean 		SD		SE_ori		NTonk_A    	TR1		1		34		8.75		NA		100Tonk_A    	TR2		2		52		15.25		NA		100Tonk_A    	TR3		3		46		12.5		NA		100Tonk_A    	TR4		4		56		25		NA		100Tonk_A    	TR5		5		39		10.75		NA		100Tonk_A    	TR6		6		49		15.25		NA		100Tonk_A    	TR7		7		23.5		4.5		NA		100Kichigina_B	8473		1		3.9		NA		1.1		5Kichigina_B	3654		2		2.4		NA		0.35		5Kichigina_B	2759		3		1.4		NA		0.15		5Kichigina_B	1903		4		7		NA		1.1		5Carlucci_C 	BF144		1		8.2		3.1		NA		10Carlucci_C 	BF47		2		10.8		1.1		NA		10Carlucci_C 	BF12		3		11.8		1.9		NA		10Lawrence_D	GARDENER	1		6.2		NA		2.1		5Lawrence_D	PHEASANT	2		5.3		NA		3		5Lawrence_D	PRAIRIE	3		14.2		NA		3.9		5Zhang_E	Merlot		1		20		NA		1		10Zhang_E	Syrah		2		23.5		NA		1		10Zhang_E	Concord	3		27.2		NA		1.4		10Driver_F	GPD3-OE1	1		1.8		NA		0.4		3Driver_F	GPD3-OE2	2		2.6		NA		0.6		3Driver_F	GPD3-OE3	3		3		NA		1.3		3Zhou_G	RG2		1		0.8		0.3		NA		3Zhou_G	RG6		2		0.9		0.35		NA		3Zhou_G	RG14		3		0.8		0.5		NA		3Zhou_G	RG20		4		2.1		0.5		NA		3Clark_H	R89/1		1		18.5		0.577		NA		4Clark_H	R89/4		2		19.3		0.5		NA		4Clark_H	R90/6		3		17.8		0.957		NA		4Clark_H	R91/7		4		20		0.816		NA		4")mydf2 <- read.table(textConnection(original_data), header=TRUE)head(mydf2)mydf2$SE <- mydf2$SD / sqrt(mydf2$N)mydf2$SE <- dplyr::coalesce(mydf2$SE, mydf2$SE_ori) ## Section 2.1. Combining p-values; triple-result joint probability and Fisher's method. Imaginary examples.pvaluesA <- c(0.007, 0.5, 0.5)pvaluesB <- c(0.12, 0.12, 0.12)pvaluesC <- c(0.049, 0.049, 0.049)pvaluesD <- c(0.05, 0.05, 0.05)pvalues <- c(paste0(pvaluesA, collapse = ", "), paste0(pvaluesB, collapse = ", "), paste0(pvaluesC, collapse = ", "), paste0(pvaluesD, collapse = ", "))description <- c("no coherence", "all non-significant", "(positive) coherence", "(positive) coherence")## triplejoint = triple-result joint probability assuming (positive) coherence results across replicates (three replicates individually significant), with joint probability under independence with each replicate unbiased. Cut-off is p=1.25×10-4:triplejointA <- prod(pvaluesA)triplejointB <- prod(pvaluesB)triplejointC <- prod(pvaluesC)triplejointD <- prod(pvaluesD)triplejoint <- signif(c(triplejointA, triplejointB, triplejointC, triplejointD), 3)sigtriple <- list(); for (i in 1:length(triplejoint)) {if (triplejoint[[i]] <= 1.25e-04) {sigtriple[[i]] <- "significant"} else {sigtriple[[i]] <- "not significant"}}sigtriple <- as.vector(unlist(sigtriple))## Fm_altered = similar to Fisher's method but with 2 degrees of freedom (identical algebraically to triplejoint above):combinedA <- -2 * sum(log(pvaluesA))Fm_alteredA <- pchisq(combinedA, df = 2, lower.tail = FALSE)combinedB <- -2 * sum(log(pvaluesB))Fm_alteredB <- pchisq(combinedB, df = 2, lower.tail = FALSE)combinedC <- -2 * sum(log(pvaluesC))Fm_alteredC <- pchisq(combinedC, df = 2, lower.tail = FALSE)combinedD <- -2 * sum(log(pvaluesD))Fm_alteredD <- pchisq(combinedD, df = 2, lower.tail = FALSE)Fm_altered <- signif(c(Fm_alteredA, Fm_alteredB, Fm_alteredC, Fm_alteredD), 3)## Fm = Fisher's method with combined p-values (for aggregate null); allowing non-coherent aggregate extremeness to become significant. Cut-off is p=0.05:combinedA <- -2 * sum(log(pvaluesA))FmA <- pchisq(combinedA, df = 6, lower.tail = FALSE)combinedB <- -2 * sum(log(pvaluesB))FmB <- pchisq(combinedB, df = 6, lower.tail = FALSE)combinedC <- -2 * sum(log(pvaluesC))FmC <- pchisq(combinedC, df = 6, lower.tail = FALSE)combinedD <- -2 * sum(log(pvaluesD))FmD <- pchisq(combinedD, df = 6, lower.tail = FALSE)Fm <- signif(c(FmA, FmB, FmC, FmD), 3)sigFm <- list(); for (i in 1:length(triplejoint)) {if (triplejoint[[i]] < 0.05) {sigFm[[i]] <- "significant"} else {sigFm[[i]] <- "not significant"}}sigFm <- as.vector(unlist(sigFm))pvaluedf <- data.frame(pvalues, description, triplejoint, Fm_altered, sigtriple, Fm, sigFm)colnames(pvaluedf) <- c("pvalues", "Individual significances", "triplejoint_p", "Fm_altered_p", "sigtriple<0.000125", "Fm_p", "sigFm<0.05")descriptionrow <- c("", "(borderline)", "", "", "", "", "")pvaluedf2 <- rbind(pvaluedf, descriptionrow)print(pvaluedf2, row.names=FALSE)## Table S11.T2 (print(pvaluedf2, row.names=FALSE)). Comparison of three methods of combining the p-value lists.## column definitions:## pvalues = imaginary sets of p-values.## Individual significances = descriptions of individual significances across replicates.## triplejoint_p = joint probability under independence.## Fm_altered_p = similar to Fisher's method but with non-standard 2 degrees of freedom (2dp); this is algebraically identical to triplejoint_p.## sigtriple<0.000125 = joint significance determination of triplejoint_p. This requires positive coherence across replicates (all three p-values <0.05) - necessarily bringing joint p-value below 1.25x10-4.## Fm_p = Fisher's method p-value - designed for independent experiments with none individually conclusive or with very weak evidence ignoring the possibility of false positives due to systematic errors (see main article).## sigFm<0.05 = joint significance determination of Fm_p.##              pvalues Individual significances triplejoint_p Fm_altered_p sigtriple<0.000125   Fm_p  sigFm<0.05##      0.007, 0.5, 0.5             no coherence       0.00175      0.00175    not significant 0.0481 significant##     0.12, 0.12, 0.12      all non-significant       0.00173      0.00173    not significant 0.0477 significant##  0.049, 0.049, 0.049     (positive) coherence      0.000118     0.000118        significant  0.006 significant##     0.05, 0.05, 0.05     (positive) coherence      0.000125     0.000125        significant 0.0063 significant##                                  (borderline)                                                                 ## Section 2.2. Greenwood statistic (for cumulative k) normalized: Gw, for imaginary example at lowest "subject" level (which is mostly not relevant for batch replication - analyzed later).x2 <- c(2, 6.5); y2 <- c(2, 2.4); x3 <- c(2, 6.5, 11); y3 <- c(2, 2.4, 10) names <- c("x2", "y2", "x3", "y3")mydata <- c("\"2, 6.5\"", "\"2, 2.4\"", "\"2, 6.5, 11\"", "\"2, 2.4, 10\"")datalist <- list(c(2, 6.5), c(2, 2.4), c(2, 6.5, 11), c(2, 2.4, 10)) means <- lapply(datalist, mean)sds <- lapply(datalist, function (x) signif(sd(x), 2))## Note: t.test is only used to get the 95% confidence interval (CI), not the one-sample t-test !myCI2 <- lapply(datalist, function (x) signif(t.test(x)$conf.int[1:2], 3)) myCI <- lapply (myCI2, function (x) paste0(x, collapse = ":"))ranges <- lapply(datalist, function (x) max(x) - min(x))gaps2 <- lapply(datalist, diff)gaps <- lapply (gaps2, function (x) paste0(x, collapse = ","))sqratio <- Map(function(g, r) (g / r)^2, gaps2, ranges)mygreen <- lapply(sqratio, sum)myfloor <- lapply(datalist, function (x)  1/(length(x) - 1)) Gw <- list(); for (i in 1:length(mygreen)) {if ((1 - myfloor[[i]]) != 0) {Gw[[i]] <- (mygreen[[i]] - myfloor[[i]]) / (1 - myfloor[[i]]) ## normalized so that floor is zero}}Gw <- Map(function(x) if (is.null(x)) NA else x, Gw) ## converts NULL to NA in list - in this case lapply didn't workmydf <- rbind(mydata, gaps, myfloor, mygreen, Gw, sds, myCI, means)mydf <- as.data.frame(mydf)colnames(mydf) <- namesrownames(mydf) <- c("data", "gaps", "floor", "Greenwood", "Normalized Greenwood (Gw)", "sd", "CI", "mean")mydf["Greenwood", "x2"] <- "1 (NA)"mydf["Greenwood", "y2"] <- "1 (NA)"mydf## TABLE S11.T3 (mydf). Greenwood statistics for imaginary examples with either two (x2 or y2) or three (x3 or y3) values.## sd(x3) and sd(y3) are identical (to 2 significant figures), but Gws are very different.## additionally: Greenwood(x2) and Greenwood(y2) are both invalid (NA = not applicable) because the Greenwood statistic is always 1 at n=2, and Gw(x2) and Gw(y2) cannot be calculated because this would require dividing by zero, giving NA.## rowname definitions:## data = imaginary data.## gaps = gaps between datapoints - used in calculation of Greenwood statistic.## floor = minimum number for Greenwood statistic - maximum is always 1.## Greenwood = Greenwood statistic, not normalized: minimum (floor) changes with n.## Gw = Greenwood statistic normalized according to floor: ranges from 0 to 1.## sd = standard deviation.## CI = 95% confidence interval for mean (assuming t distribution).## mean = mean.##                                   x2          y2           x3           y3## data                        "2, 6.5"    "2, 2.4" "2, 6.5, 11" "2, 2.4, 10"## gaps                             4.5         0.4      4.5,4.5      0.4,7.6## floor                              1           1          0.5          0.5## Greenwood                     1 (NA)      1 (NA)          0.5        0.905## Normalized Greenwood (Gw)         NA          NA            0         0.81## sd                               3.2        0.28          4.5          4.5## CI                        -24.3:32.8 -0.341:4.74   -4.68:17.7      -6.4:16## mean                            4.25         2.2          6.5          4.8## Section 2.3. Normalized Greenwood calculations for real-world data (from Section 1), idealized to show possible effects at the lowest "subject" level (i.e., not analyzing batch replication in this section). ## NOTE: in this section the actual data comes from means which are being treated as individual datapoints - and this section is only for the illustration of the normalized Greenwood statistic (Gw) in reference to what sometimes happens in the treatment of the lowest "subject" level of other studies (studies not shown here). In other words the fact that (in the original studies used here) each mean actually came with its own variance is totally ignored in this section (but not in later sections). The terms ISD and ICI are used to refer to calculated interpoint SDs and CIs (not the actual SDs or CIs from the data), and ISD/ICI only illustrate how the standard deviations (or confidence intervals) would change with increasing k if the datapoints (the means) were treated as individual datapoints (note there are real-world situations (see examples in S5), in which means are actually treated as individual datapoints). The relevant illustration is that the ISDs/ICIs sometimes contrast with Gws - see Discussion.names <- unique(mydf2$study)namesxxx <- list(); yyy <- list(); rangeyyy <- list(); gapsyyy <- list(); sqratioy <- list(); greeny <- list(); floor <- list(); Gw <- list(); ISD <- list(); myICI2 <- list(); myICI <- list(); for (i in 1:length(names)) {xxx[[i]] <- mydf2[which(mydf2$study == names[[i]]), "mean"] greeny[[i]] <- list(); yyy[[i]] <- list(); rangeyyy[[i]] <- list(); gapsyyy[[i]] <- list(); sqratioy[[i]] <- list(); greeny[[i]] <- list(); floor[[i]] <- list(); Gw[[i]] <- list(); ISD[[i]] <- list(); myICI2[[i]] <- list(); myICI[[i]] <- list(); for (j in 2:length(xxx[[i]])) {yyy[[i]][[j]] <- xxx[[i]][1:j]floor[[i]][[j]] <- 1/(length(yyy[[i]][[j]]) - 1)rangeyyy[[i]][[j]] <- max(yyy[[i]][[j]]) - min(yyy[[i]][[j]])gapsyyy[[i]][[j]] <- diff(sort(yyy[[i]][[j]]))sqratioy[[i]][[j]]  <- (gapsyyy[[i]][[j]] /rangeyyy[[i]][[j]] )^2greeny[[i]][[j]] <- sum(sqratioy[[i]][[j]])ISD[[i]][[j]] <- sd(yyy[[i]][[j]])myICI2[[i]][[j]] <- signif(t.test(yyy[[i]][[j]])$conf.int[1:2], 3)myICI[[i]][[j]] <- paste0(myICI2[[i]][[j]], collapse = ":")Gw[[i]][[j]] <- (greeny[[i]][[j]] - floor[[i]][[j]]) / (1 - floor[[i]][[j]])if (Gw[[i]][[j]] == "NaN") {Gw[[i]][[j]] <- NA} ## from if (length} ## from for (i in 1} ## from for (j in 1## convert NULL to NA in list:Gw <- sapply(Gw, function(x) unlist(lapply(x, function(x) ifelse(is.null(x), NA, x))))greeny <- sapply(greeny, function(x) unlist(lapply(x, function(x) ifelse(is.null(x), NA, x))))Gw <- as.vector(unlist(Gw))Gw <- round(Gw, 3)greeny <- as.vector(unlist(greeny))greeny <- round(greeny, 2)mydf2$Gw <- Gwmydf2 <- relocate(mydf2, c("Gw"), .after = mean)ISD <- sapply(ISD, function(x) unlist(lapply(x, function(x) ifelse(is.null(x), NA, x))))ISD <- as.vector(unlist(ISD))ISD <- round(ISD, 3)mydf2$ISD <- ISDmydf2 <- relocate(mydf2, c("ISD"), .after = mean)ICI <- sapply(myICI, function(x) unlist(lapply(x, function(x) ifelse(is.null(x), NA, x))))ICI <- as.vector(unlist(ICI))mydf2$ICI <- ICImydf2 <- relocate(mydf2, c("ICI"), .after = mean)mydf2[ , 1:7]## Note that Lawrence_D and Zhang_E have similar n=3 ISDs but very different Gws (also compare n=4 Zhou_G, Clark_H) similar to the imaginary example in Section 2.2:## TABLE S11.T4 (mydf2[ , 1:7]). Greenwood statistics for actual data (with means treated as individual datapoints).## column definitions:## study = study from section 1. ## level = level as found in original article ## k = order of level as in original article (also number of replicates included in an analysis)## mean = mean from original article## ICI = 95% confidence interval of datapoints from 1 to k (means treated as individual datapoints).## ISD = standard deviation calculated from 1 to k (means treated as individual datapoints).## Gw = normalized Greenwood statistic calculated from 1 to k ) (means treated as individual datapoints).##          study    level k mean         ICI    ISD    Gw## 1       Tonk_A      TR1 1 34.0        <NA>     NA    NA## 2       Tonk_A      TR2 2 52.0   -71.4:157 12.728    NA## 3       Tonk_A      TR3 3 46.0   21.2:66.8  9.165 0.111## 4       Tonk_A      TR4 4 56.0   31.7:62.3  9.592 0.107## 5       Tonk_A      TR5 5 39.0   34.2:56.6  9.044 0.014## 6       Tonk_A      TR6 6 49.0   37.4:54.6  8.222 0.029## 7       Tonk_A      TR7 7 23.5   32.3:53.3 11.343 0.048## 8  Kichigina_B     8473 1  3.9        <NA>     NA    NA## 9  Kichigina_B     3654 2  2.4  -6.38:12.7  1.061    NA## 10 Kichigina_B     2759 3  1.4 -0.559:5.69  1.258 0.040## 11 Kichigina_B     1903 4  7.0 -0.213:7.56  2.443 0.115## 12  Carlucci_C    BF144 1  8.2        <NA>     NA    NA## 13  Carlucci_C     BF47 2 10.8    -7.02:26  1.838    NA## 14  Carlucci_C     BF12 3 11.8   5.65:14.9  1.858 0.198## 15  Lawrence_D GARDENER 1  6.2        <NA>     NA    NA## 16  Lawrence_D PHEASANT 2  5.3 0.0322:11.5  0.636    NA## 17  Lawrence_D  PRAIRIE 3 14.2   -3.6:20.7  4.899 0.636## 18     Zhang_E   Merlot 1 20.0        <NA>     NA    NA## 19     Zhang_E    Syrah 2 23.5   -0.486:44  2.475    NA## 20     Zhang_E  Concord 3 27.2   14.6:32.5  3.600 0.001## 21    Driver_F GPD3-OE1 1  1.8        <NA>     NA    NA## 22    Driver_F GPD3-OE2 2  2.6  -2.88:7.28  0.566    NA## 23    Driver_F GPD3-OE3 3  3.0  0.949:3.98  0.611 0.111## 24      Zhou_G      RG2 1  0.8        <NA>     NA    NA## 25      Zhou_G      RG6 2  0.9  0.215:1.49  0.071    NA## 26      Zhou_G     RG14 3  0.8  0.69:0.977  0.058 1.000## 27      Zhou_G     RG20 4  2.1  0.139:2.16  0.635 0.787## 28     Clark_H    R89/1 1 18.5        <NA>     NA    NA## 29     Clark_H    R89/4 2 19.3     13.8:24  0.566    NA## 30     Clark_H    R90/6 3 17.8   16.7:20.4  0.751 0.004## 31     Clark_H    R91/7 4 20.0   17.4:20.4  0.956 0.002## Section 3. Confidence interval widths, actual and expected.## From now on, the data is being treated as given in the original data, i.e., with batch replication where each level has its own mean and variance.## SEp is pooled standard error (SE): relationship with standard deviation (SD) is given by Ruxton (2006): SEp=sp/sqrt(n * k) where sp is pooled SD. SE is NOT sp/sqrt(n/k) = sp * sqrt(k/n), which would be for analyzing differences.## Functions (in green)  identical to those in Supplemental File S7.## NOsys## means = original means from data## ss = either original SDs or original SEs from data (depending on s_method)## s_method = method to use either SDs or SEs from original data## ns = list of sample sizes from original data (usually all the same number)## alpha = significance p-value cut-off## Welch = Welch-Satterthwaite adjustmentglobal_mean_CI_nosys <- function(means, ss, s_method = c("sd", "SE"), ns, alpha = 0.05, Welch = FALSE) {  s_method <- match.arg(s_method)  k <- length(means)  total_n <- sum(ns)  weights <- ns / total_nglobal_mean <- sum(weights * means)  if (s_method == "sd") {sds <- ssvar_total <- sum((sds^2 / ns) * (weights^2))var_i <- (weights^2 * sds^2) / ns  } else if (s_method == "SE") {SE <- ssvar_total <- sum((weights^2) * (SE^2))var_i <- (weights^2 * SE^2)}SE_total <- sqrt(var_total)if (Welch == TRUE) {df_num <- var_total^2df_den <- sum(var_i^2 / (ns - 1)) ## Welch–Satterthwaite df correction - differing variancesdf <- df_num / df_den} else {df <- sum(ns - 1)} t_crit <- qt(p = (1 - alpha/2), df)CI_lower <- global_mean - t_crit * SE_totalCI_upper <- global_mean + t_crit * SE_totalCIwidth <- 2*t_crit * SE_totalExpCIwidth <- 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns)) ## sample sizes across k are allowed to differ using sqrt(sum(ns)) rather than sqrt(k)return(c(CIwidth = CIwidth, ExpCIwidth = ExpCIwidth))}mydf2 <- mydf2 %>% mutate(study = factor(study, levels = unique(study)))##NOsys map_dfrmydf <- mydf2 %>%  group_split(study) %>%  map_dfr(function(df_study) {    out <- vector("list", nrow(df_study))    for (i in seq_len(nrow(df_study))) {      chunk <- df_study[1:i, ]      resultNoW <- global_mean_CI_nosys(        means = chunk$mean,        ss = chunk$SE,        s_method = "SE",        ns = chunk$N,        Welch = FALSE      )      resultW <- global_mean_CI_nosys(        means = chunk$mean,        ss = chunk$SE,        s_method = "SE",        ns = chunk$N,        Welch = TRUE      )      myresult <- c(CIwidth_NoW = unname(resultNoW["CIwidth"]),                    CIwidth_W   = unname(resultW["CIwidth"]),                    ExpCIwidth  = unname(resultNoW["ExpCIwidth"]))      out[[i]] <- cbind(df_study[i, ], t(myresult))    }    bind_rows(out)  })mydf$CIwidth_NoWmydf$CIwidth_Wmydf$ExpCIwidthmydf <- mydf %>%  group_by(study) %>%  mutate(    ref_CI_NoW = CIwidth_NoW[k == 2][1],    ref_CI_W   = CIwidth_W[k == 2][1],    relCIwidth_NoW = 100 * CIwidth_NoW / ref_CI_NoW,    relCIwidth_W   = 100 * CIwidth_W / ref_CI_W,    refExp_CI = ExpCIwidth[k == 2][1],    relExpCIwidth = 100 * ExpCIwidth / refExp_CI,    adjExpCIwidth_NoW = (ref_CI_NoW / refExp_CI) * ExpCIwidth,    adjExpCIwidth_W   = (ref_CI_W / refExp_CI) * ExpCIwidth  ) %>%  ungroup()mydf <- as.data.frame(mydf)## SYSglobal_mean_CI_sys <- function(means, ss, s_method = c("sd", "SE"), ns, alpha = 0.05, sys_method = c("var", "range"), Welch = FALSE) {  sys_method <- match.arg(sys_method)  s_method <- match.arg(s_method)    k <- length(means)  total_n <- sum(ns)  weights <- ns / total_n  global_mean <- sum(weights * means)  if (s_method == "sd") {sds <- ssvar_sampling <- sum((sds^2 / ns) * (weights^2))var_i <- (weights^2 * sds^2) / ns  } else if (s_method == "SE") {SE <- ssvar_sampling <- sum((weights^2) * (SE^2))var_i <- (weights^2 * SE^2)} if (sys_method == "var") {  if (k > 1) {    var_sys <- sum((means - global_mean)^2) / (k*(k - 1))  ## NOTE: this is the standard error of the grand mean estimated from the variance among the means, with Bessel's correction used for actual data  } else {    var_sys <- 0  }} else if (sys_method == "range") {  delta <- max(means) - min(means)  var_sys <- (delta / 2)^2 / k ## NOTE this range estimate of var_sys is crude, probably needs further adjustments for precision use, and was not used further in this article.}  var_total <- var_sampling + var_sys  SE_total <- sqrt(var_total)if (Welch == TRUE) {  df_samp <- var_sampling^2 / sum((var_i^2) / (ns - 1))   ## Welch's adjustment if (var_sys > 0) { ## Welch–Satterthwaite also adjusts df for t_crit from var_sys:  df <- (var_sampling + var_sys)^2 / ((var_sampling^2 / df_samp) + (var_sys^2 / (k - 1)))} else {  df <- df_samp} ## from if (var_sys } else {  df <- sum(ns - 1)   ## no Welch's: equal underlying variances assumed; pooled df. ## This is the same df as used for ExpCIwidth, so t_crit cancels in the ratio.} ## from if (Welch t_crit <- qt(1 - alpha / 2, df)   CI_lower <- global_mean - t_crit * SE_total  CI_upper <- global_mean + t_crit * SE_total  CI_sys_width <- 2*t_crit * SE_total  ExpCIwidth <- 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns))return(c(CI_sys_width = CI_sys_width, ExpCIwidth = ExpCIwidth, var_sampling = var_sampling, var_sys = var_sys))}##SYS map_dfrmydf <- mydf %>%  group_split(study) %>%  map_dfr(function(df_study) {    out <- vector("list", nrow(df_study))    for (i in seq_len(nrow(df_study))) {      chunk <- df_study[1:i, ]      resultNoW <- global_mean_CI_sys(        means = chunk$mean,        ss = chunk$SE,                      s_method = "SE",             ## or "sd" if needed        ns = chunk$N,        sys_method = "var",          ## "var" or "range"        Welch = FALSE      )      resultW <- global_mean_CI_sys(        means = chunk$mean,        ss = chunk$SE,                      s_method = "SE",                     ns = chunk$N,        sys_method = "var",                  Welch = TRUE      )      myresult <- c(CI_sys_width_NoW = unname(resultNoW["CI_sys_width"]),                    CI_sys_width_W   = unname(resultW["CI_sys_width"]),                    var_sampling     = unname(resultNoW["var_sampling"]),                    var_sys          = unname(resultNoW["var_sys"]))      out[[i]] <- cbind(df_study[i, ], t(myresult))    }    bind_rows(out)  })mydf$CI_sys_width_NoWmydf$CI_sys_width_Wmydf <- mydf %>%  group_by(study) %>%  mutate(    refCI_sys_NoW = CI_sys_width_NoW[k == 2][1],    refCI_sys_W   = CI_sys_width_W[k == 2][1],    relCI_sys_NoW = 100 * CI_sys_width_NoW / refCI_sys_NoW,    relCI_sys_W   = 100 * CI_sys_width_W / refCI_sys_W,    adj_sys_ExpCIwidth_NoW = (refCI_sys_NoW / refExp_CI) * ExpCIwidth,    adj_sys_ExpCIwidth_W   = (refCI_sys_W / refExp_CI) * ExpCIwidth  ) %>%  ungroup()study_order <- unique(mydf$study)mydf <- mydf %>% mutate(study = factor(study, levels = study_order))mydf <- as.data.frame(mydf)mydfmydf_display <- mydf %>% select(c(study, N, k, mean, SE, ExpCIwidth, CIwidth_NoW, CIwidth_W, adjExpCIwidth_NoW, adjExpCIwidth_W, CI_sys_width_NoW, CI_sys_width_W, adj_sys_ExpCIwidth_NoW, adj_sys_ExpCIwidth_W))mydf_display <- signif_df(mydf_display, 4)colnames(mydf_display) <- gsub("width", "", colnames(mydf_display))colnames(mydf_display) <- gsub("__", "_", colnames(mydf_display))mydf_display ## TABLE S11.T5 (mydf_display). 95% confidence interval (CI) widths from actual data, together with adjusted expected CI widths (adjusted relative to ratio between k=2 actual and expected).## column definitions: "width" has been removed from the colnames in mydf for mydf_display to save space.## study = study from section 1.## N = number of samples for that level.## k = order of level as in original article (also number of replicates included in an analysis).## mean = mean from original article.## SE = standard error, either from original article or calculated from original SD.## ExpCI = expected confidence-interval width = 2*qt((1-alpha/2), df = sum(ns - 1)) / sqrt(sum(ns)) where qt is the quantile function for the Student's t-distribution for critical value (1-alpha/2) and degrees of freedom given by the sample sizes (ns). ## CI_NoW = actual 95% confidence-interval width = 2*t_crit * SE_total where SE_total = sqrt(sum((weights^2) * (SE^2))) or sqrt(sum((weights^2) * (sds^2 / ns))).## CI_W = CI_NoW with Welch-Satterthwaite adjustment.## adjExpCI_NoW = (ref_CI_NoW / refExp_CI) * ExpCI = ExpCI (defined above) adjusted by the ratio of CI_NoW at k=2 divided by ExpCI at k=2.## adjExpCI_W = adjExpCI_NoW with Welch-Satterthwaite adjustment.## CI_sys_NoW = 2*t_crit * SE_total where SE_total = sqrt(var_sampling + var_sys) and  var_sys = sum((means - global_mean)^2) / (k*(k - 1)); and var_sampling = sum((weights^2) * (SE^2)) or var_sampling = sum((weights^2) * (sds^2 / ns)); where weights <- ns / total_n.## CI_sys_W = CI_sys_NoW with Welch-Satterthwaite adjustment.## adj_sys_ExpCI_NoW = (refCI_sys_NoW / refExp_CI) * ExpCI = ExpCI (defined above) adjusted by the ratio of CI_sys_NoW at k=2 divided by ExpCI at k=2.## adj_sys_ExpCI_W = adj_sys_ExpCI_NoW with Welch-Satterthwaite adjustment. ## Note 1: ExpCI is unaffected by the Welch setting, so adjExpCI_NoW/adjExpCI_W and adj_sys_ExpCI_NoW/adj_sys_ExpCI_W differ only through their k=2 anchors; within each study these columns are therefore ExpCI multiplied by a single study-specific constant. This is why they differ at k=1 even though CI_NoW and CI_W are identical there (at k=1 the Welch expression reduces to the pooled df).## Note 2: the Welch adjustment has little effect on CI_NoW/CI_W (mostly under 1%) but a large effect on CI_sys_NoW/CI_sys_W, because once var_sys greatly exceeds var_sampling the combined Welch degrees of freedom fall towards k-1 and t_crit rises sharply (e.g. Tonk at k=2). Zhou_G is an exception because var_sys is small relative to var_sampling and the Welch df exceeds the pooled df.## mydf_display ##          study   N k mean     SE  ExpCI  CI_NoW    CI_W adjExpCI_NoW adjExpCI_W CI_sys_NoW CI_sys_W adj_sys_ExpCI_NoW adj_sys_ExpCI_W## 1       Tonk_A 100 1 34.0 0.8750 0.3968  3.4720  3.4720       4.9340     4.9410     3.4720   3.4720           50.7500        312.8000## 2       Tonk_A 100 2 52.0 1.5250 0.2789  3.4670  3.4730       3.4670     3.4730    35.6700 219.8000           35.6700        219.8000## 3       Tonk_A 100 3 46.0 1.2500 0.2272  2.8300  2.8320       2.8250     2.8300    21.0200  44.4100           29.0600        179.1000## 4       Tonk_A 100 4 56.0 2.5000 0.1966  3.2460  3.2520       2.4440     2.4480    19.1300  30.0000           25.1400        155.0000## 5       Tonk_A 100 5 39.0 1.0750 0.1757  2.7290  2.7340       2.1850     2.1880    16.1300  22.2900           22.4700        138.5000## 6       Tonk_A 100 6 49.0 1.5250 0.1604  2.4830  2.4860       1.9940     1.9970    13.4200  17.2100           20.5100        126.4000## 7       Tonk_A 100 7 23.5 0.4500 0.1484  2.1430  2.1450       1.8450     1.8480    16.9700  20.9900           18.9800        117.0000## 8  Kichigina_B   5 1  3.9 1.1000 2.