          3.6010## 23    Driver_F   3 3  3.0 1.3000 1.6310  2.4250  3.0240       1.4410     1.5290     2.9770   3.0920            2.1520          2.5910## 24      Zhou_G   3 1  0.8 0.1732 4.9680  1.4900  1.4900       1.6190     1.6350     1.4900   1.4900            1.7300          1.6300## 25      Zhou_G   3 2  0.9 0.2021 2.2670  0.7389  0.7458       0.7389     0.7458     0.7894   0.7440            0.7894          0.7440## 26      Zhou_G   3 3  0.8 0.2887 1.6310  0.6405  0.6730       0.5317     0.5367     0.6610   0.6723            0.5680          0.5354## 27      Zhou_G   3 4  2.1 0.2887 1.3310  0.5619  0.5787       0.4340     0.4380     1.5690   1.9060            0.4636          0.4369## 28     Clark_H   4 1 18.5 0.2885 3.1820  1.8360  1.8360       1.7180     1.7270     1.8360   1.8360            3.9890          9.8640## 29     Clark_H   4 2 19.3 0.2500 1.7300  0.9341  0.9387       0.9341     0.9387     2.1690   5.3630            2.1690          5.3630## 30     Clark_H   4 3 17.8 0.4785 1.3060  0.9231  0.9751       0.7051     0.7086     2.1670   3.0830            1.6370          4.0480## 31     Clark_H   4 4 20.0 0.4080 1.0890  0.8014  0.8235       0.5881     0.5910     2.2310   2.8640            1.3660          3.3770## Section 4. Generalized additive model (GAM) fits:if (grW == TRUE) {grname <- "_W"} else {grname <- "_NoW"}## add duplicated columns to mydf - depending on value of grW:attr(mydf, "grW") <- grWif (grW == TRUE) {mydf$CIwidth <- mydf$CIwidth_Wmydf$ref_CI <- mydf$ref_CI_Wmydf$relCIwidth <- mydf$relCIwidth_Wmydf$adjExpCIwidth <- mydf$adjExpCIwidth_Wmydf$CI_sys_width <- mydf$CI_sys_width_Wmydf$refCI_sys <- mydf$refCI_sys_Wmydf$relCI_sys <- mydf$relCI_sys_Wmydf$adj_sys_ExpCIwidth <- mydf$adj_sys_ExpCIwidth_W} else {mydf$CIwidth <- mydf$CIwidth_NoWmydf$ref_CI <- mydf$ref_CI_NoWmydf$relCIwidth <- mydf$relCIwidth_NoWmydf$adjExpCIwidth <- mydf$adjExpCIwidth_NoWmydf$CI_sys_width <- mydf$CI_sys_width_NoWmydf$refCI_sys <- mydf$refCI_sys_NoWmydf$relCI_sys <- mydf$relCI_sys_NoWmydf$adj_sys_ExpCIwidth <- mydf$adj_sys_ExpCIwidth_NoW}mydfnamesdf <- mydf %>%  mutate(study = factor(study, levels = study_order)) %>% group_by(study) %>% summarize(.groups = "drop")namesdf$study <-  as.character(namesdf$study)names <- as.vector(namesdf$study)names## [1] "Tonk_A"      "Kichigina_B" "Carlucci_C"  "Lawrence_D" ## [5] "Zhang_E"     "Driver_F"    "Zhou_G"    "Clark_H"## NO_SYS: GAM between CIwidth and adjExpCIwidth df_NOsys <- list(); df_long_NOsys <- list(); for (i in 1:length(names)) {df_NOsys[[i]] <- mydf %>%  filter(study == names[[i]]) %>%  select(k, CIwidth, adjExpCIwidth)names(df_NOsys)[i] <- names[[i]]df_long_NOsys[[i]] <- df_NOsys[[i]] %>%  pivot_longer(cols = c(CIwidth, adjExpCIwidth),               names_to = "line_type", values_to = "CI") %>%  mutate(line_type = factor(line_type, levels = c("adjExpCIwidth", "CIwidth"))) names(df_long_NOsys)[i] <- names[[i]]}## SYS: GAM between CI_sys_width and adj_sys_ExpCIwidth df_SYS <- list(); df_long_SYS <- list(); for (i in 1:length(names)) {df_SYS[[i]] <- mydf %>%  filter(study == names[[i]]) %>%  select(k, CI_sys_width, adj_sys_ExpCIwidth)names(df_SYS)[i] <- names[[i]]df_long_SYS[[i]] <- df_SYS[[i]] %>%  pivot_longer(cols = c(CI_sys_width, adj_sys_ExpCIwidth),               names_to = "line_type", values_to = "CI") %>%  mutate(line_type = factor(line_type, levels = c("adj_sys_ExpCIwidth", "CI_sys_width"))) names(df_long_SYS)[i] <- names[[i]]}if (TYPE == "NOsys") {dfA <- df_NOsys df_longA <- df_long_NOsys}if (TYPE == "SYS") {dfA <- df_SYS df_longA <- df_long_SYS}if (TYPE == "NOsys") {NumChunkperStudyNOsys <- rep(1:8, c(2, 1, 1, 1, 1, 1, 1, 1)) ## no. of chunks per 8 studiesdf <- dfA[NumChunkperStudyNOsys] dfdf_long <- df_longA[NumChunkperStudyNOsys] df_longchunks <- list(c(1:7), c(2:6), c(1:4), c(1:3), c(1:3), c(1:3), c(1:3), c(1:4), c(1:4))names(chunks) <- names(df)chunks}if (TYPE == "SYS") {NumChunkperStudySYS <- rep(1:8, c(2, 1, 1, 1, 1, 1, 1, 1)) ## no. of chunks per 8 studiesdf <- dfA[NumChunkperStudySYS] ## gives numbers of chunks per study (8 studies)dfdf_long <- df_longA[NumChunkperStudySYS] df_long## NOTE - SYS graphs are only appropriate if they include k = 2 onwards ! i.e., without k = 1 (any SYS graphs with k = 1 are only produced for coding convenience and are subsequently removed; the k = 1 entry carries zero systematic-error information). chunks <- list(c(2:7), c(2:6), c(2:4), c(1:3), c(1:3), c(1:3), c(1:3), c(2:4), c(2:4)) names(chunks) <- names(df)chunks}namechunk <- list(); for (i in 1:length(chunks)) {namechunk[[i]] <- paste0(chunks[[i]], collapse = "")}df_chunk <- Map(function(df, ks) {  df %>% filter(k %in% ks)}, df_long, chunks)kk <- 3 ## basis for smoothing spline in generalized additive model. mod_null <- list(); mod_alt <- list(); myanova <- list(); mysummary <- list(); pp <- list(); for (i in 1:length(df_chunk)) {## Model with shared smooth across both lines mod_null[[i]] <- mgcv::gam(CI ~ s(k, k = kk), data = df_chunk[[i]])## Model with separate smooths by line_type (Zhang_E NOsys needed different model to obtain p-value for _W and _NoW (!) - note the most important tests are the tolerance band tests given later which do not rely on the p-values calculated here):if ((names(df_chunk)[i] == "Zhang_E") & (TYPE == "NOsys")) { ## no separate line_type term for Zhang_E:mod_alt[[i]] <- mgcv::gam(CI ~ s(k, by = line_type, k = kk), data = df_chunk[[i]])} else {mod_alt[[i]] <- mgcv::gam(CI ~ line_type + s(k, by = line_type, k = kk), data = df_chunk[[i]])}mysummary[[i]] <- summary(mod_alt[[i]])myanova[[i]] <- anova(mod_null[[i]], mod_alt[[i]], test = "F")names(myanova)[i] <- paste0(names(chunks)[i], "_k", namechunk[[i]], "_", TYPE, grname)pp[[i]] <- signif(myanova[[i]]$"Pr(>F)"[2], 3)}myggplot <- list(); for (i in 1:length(df_chunk)) {if ((TYPE == "NOsys") || ((TYPE == "SYS") & (chunks[[i]][[1]] != 1))) {df <- df_chunk[[i]]myggplot[[i]] <- ggplot(df, aes(x = k, y = CI, color = line_type)) +  geom_point() +   ggtitle(paste0("GAM_", names(myanova)[i], " p = ", pp[[i]])) +  geom_smooth(method = "gam", formula = y ~ s(x, k = 3), se = TRUE) +  theme(axis.title.x = element_text(size = 30), axis.title.y = element_text(size = 30), legend.text = element_text(size = 15), legend.title = element_text(size = 15), plot.title = element_text(size = 20), plot.subtitle = element_text(size = 30), text=element_text(size=21))ggsave(paste0("GAM_", TYPE, grname, i, ".pdf"), plot = myggplot[[i]], device = "pdf", path = mypath, height = 5 , width = 8)}}if (TYPE == "SYS") {myanova[4:7] <- NA}myanova## Section 4.1. GAM fits: NOsys results - No Welch-Satterthwaite adjustment.## myanova## $Tonk_A_k1234567_NOsys_NoW## Analysis of Deviance Table## ## Model 1: CI ~ s(k, k = kk)## Model 2: CI ~ line_type + s(k, by = line_type, k = kk)##   Resid. Df Resid. Dev     Df Deviance      F   Pr(>F)   ## 1   11.2927    2.02998                                   ## 2    9.0026    0.44371 2.2901   1.5863 14.129 0.001376 **## ---## Signif. codes:  0 ‘***’ 0.001 ‘**’ 0.01 ‘*’ 0.05 ‘.’ 0.1 ‘ ’ 1## ## $Tonk_A_k23456_NOsys_NoW## Analysis of Deviance Table## ## Model 1: CI ~ s(k, k = kk)## Model 2: CI ~ line_type + s(k, by = line_type, k = kk)##   Resid. Df Resid. Dev     Df Deviance      F  Pr(>F)  ## 1    8.0000    0.74056                                 ## 2    5.3252    0.23636 2.6748   0.5042 4.4424 0.06796 .## ---## Signif. codes:  0 ‘***’ 0.001 ‘**’ 0.01 ‘*’ 0.05 ‘.’ 0.1 ‘ ’ 1## ## $Kichigina_B_k1234_NOsys_NoW## Analysis of Deviance Table## ## Model 1: CI ~ s(k, k = kk)## Model 2: CI ~ line_type + s(k, by = line_type, k = kk)##   Resid. Df Resid. Dev     Df Deviance      F Pr(>F)## 1    5.0087    1.48809                              ## 2    2.0185    0.17265 2.9902   1.3154 5.5046  0.156## ## $Carlucci_C_k123_NOsys_NoW## Analysis of Deviance Table#