## Section 8. Do points lie within 25% of the expected decreasing curve ?## Section 8.1. NOsys data with 25% bands. Data from CIdf_list (re-created here from original_data).myprefix <- c("Tonk", "Kich", "Carl", "Lawr", "Zhan", "Driv", "Zhou", "Clark") CIdf_list <- list(); for (i in 1:length(names)) {sub <- mydf[mydf$study == names[[i]], ]sub <- sub[order(sub$k), ]mydfband <- data.frame(sub$k,                       100 * signif(sub$CIwidth_NoW / sub$ref_CI_NoW, 4),                       100 * signif(sub$CIwidth_W / sub$ref_CI_W, 4),                       100 * signif(sub$ExpCIwidth / sub$refExp_CI, 4))colnames(mydfband) <- c("k", paste0(myprefix[i], "_Act_NoW"), paste0(myprefix[i], "_Act_W"), paste0(myprefix[i], "_Exp"))CIdf_list[[i]] <- mydfband}names(CIdf_list) <- myprefixCIdf_list## TABLE S11.T6 (re-created here from original_data; identical to S7.T14). (CIdf_list). Actual and expected 95% confidence interval widths, from sampling error alone as ratios of that at k=2, from function global_mean_CI_nosys. ## column definitions (columns match S7 TABLE S7.T14):## k = number of replicates included for this row's data## _Act_NoW = actual ratio of confidence interval width (sampling error only) relative to that at k=2. CIwidth = 2*t_crit*SE_total, where SE_total = sqrt(var_total), var_total = sum((weights^2) * (sds^2 / ns)) for studies supplying SDs or sum((weights^2) * (SE^2)) for studies supplying SEs, and weights = ns/total_n. Degrees of freedom for t_crit are pooled, df = sum(ns-1); no Welch's adjustment. ## _Act_W = as _Act_NoW, but with Welch–Satterthwaite adjustment.## _Exp = expected ratio of confidence interval width (sampling error only) relative to that at k=2. ExpCIwidth = 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns)). This always uses the pooled df and is therefore unaffected by the Welch setting.## CIdf_list## $Tonk##   k Tonk_Act_NoW Tonk_Act_W Tonk_Exp## 1 1       100.10      99.99   142.30## 2 2       100.00     100.00   100.00## 3 3        81.63      81.56    81.48## 4 4        93.62      93.64    70.49## 5 5        78.71      78.72    63.01## 6 6        71.61      71.58    57.50## 7 7        61.79      61.78    53.22## $Kich##   k Kich_Act_NoW Kich_Act_W Kich_Exp## 1 1       229.50     203.30   170.30## 2 2       100.00     100.00   100.00## 3 3        63.52      66.54    77.15## 4 4        63.77      60.35    65.00## $Carl##   k Carl_Act_NoW Carl_Act_W Carl_Exp## 1 1       203.00     194.20   152.30## 2 2       100.00     100.00   100.00## 3 3        75.19      73.81    79.74## $Lawr##   k Lawr_Act_NoW Lawr_Act_W Lawr_Exp## 1 1       138.10     135.30   170.30## 2 2       100.00     100.00   100.00## 3 3        92.02      92.35    77.15## $Zhan##   k Zhan_Act_NoW Zhan_Act_W Zhan_Exp## 1 1       152.30     152.30   152.30## 2 2       100.00     100.00   100.00## 3 3        91.62      92.12    79.74## $Driv##   k Driv_Act_NoW Driv_Act_W Driv_Exp## 1 1        171.9      162.0   219.20## 2 2        100.0      100.0   100.00## 3 3        121.1      142.3    71.96## $Zhou##   k Zhou_Act_NoW Zhou_Act_W Zhou_Exp## 1 1       201.70     199.80   219.20## 2 2       100.00     100.00   100.00## 3 3        86.68      90.24    71.96## 4 4        76.04      77.59    58.73## $Clark##   k Clark_Act_NoW Clark_Act_W Clark_Exp## 1 1        196.60      195.60    183.90## 2 2        100.00      100.00    100.00## 3 3         98.83      103.90     75.48## 4 4         85.79       87.73     62.96band_check <- function(k, act_pct_NoW, act_pct_W, exp_pct, kind = c("nosys","sys"),                       tau   = 1.25,   ## ratio band: observed within +/-25% of expected                       delta = 25) {   ## absolute band: within 25 pp (% of k=2 CI expected width)  kind <- match.arg(kind)  rN    <- act_pct_NoW / exp_pct         ## observed/expected; r == 1 at k = 2 by construction  rW    <- act_pct_W / exp_pct  gapN  <- act_pct_NoW - exp_pct         ## vertical gap in pp (both are % of the k = 2 CI width)  gapW  <- act_pct_W - exp_pct  info  <- k >= 3                        ## k = 1 unpooled start, k = 2 anchor -> both non-informative  data.frame(k,             actualCI_NoW = round(act_pct_NoW, 1),             actualCI_W = round(act_pct_W, 1),             expCI = round(exp_pct, 1),             ## ratio_NoW   = round(rN, 3),             ## ratio_W     = round(rW, 3),             ratiodiff_NoW = round(100 * (rN - 1), 1),   ## relative deviation (ratio criterion)             ratiodiff_W   = round(100 * (rW - 1), 1),             adddiff_NoW = round(gapN, 1),               ## absolute deviation (pp criterion)             adddiff_W   = round(gapW, 1),             informative = info,             in_ratioband_NoW = ifelse(info, rN >= 1/tau & rN <= tau, NA),   ## within +/-25%             in_ratioband_W   = ifelse(info, rW >= 1/tau & rW <= tau, NA),             in_addband_NoW = ifelse(info, abs(gapN) <= delta, NA),          ## within 25 pp             in_addband_W   = ifelse(info, abs(gapW) <= delta, NA))}bandlistNOsys <- list(); for (i in 1:length(CIdf_list)) {d <- CIdf_list[[i]]bandlistNOsys[[i]] <- band_check(d[[1]], d[[2]], d[[3]], d[[4]], "nosys")names(bandlistNOsys)[i] <- myprefix[[i]]}print(bandlistNOsys, row.names = FALSE)## TABLE S11.T7 (bandlistNOsys). NOsys results showing which points lie within 25% expected tolerance bands (either relative at each k or "absolute" = relative to k=2).## column definitions: (suffixes _W and _NoW are with or without Welch-Satterthwaite adjustment, respectively.)## k = replicate number: how many of the study's groups (levels) have been accumulated into the running pooled estimate. k=1 is a single, unpooled group; k=2 gives the first two groups pooled; and so on. ## actualCI columns show observed ("actual") CI width at this k (from sampling error alone), as a percentage of the study's observed k=2 CI width (100 x CIwidth(k) / CIwidth(k=2)). This is 100 at k=2 by construction. Lower values (<100) mean the real CI has narrowed as replicates accumulate. ## expCI = expected CI width at each k, on the same scale as actual_CI  (100x adjExp(k)/CIwidth(k=2)). This is the idealised 1/sqrt(k) narrowing curve - giving the CI width if adding replicates reduced it purely by sampling theory. This is anchored so it equals the observed value (100) at k=2, i.e., it is also 100 at k=2 by construction. ## ratiodiff columns show multiplicative discrepancy as a percentage: 100 x (ratio−1). This is the quantity the relative band judges (note the band is multiplicative, so the limits are −20% to +25%). Assessed in in_ratioband columns. Where ratio = actual_CI/exp_CI (equivalently: CI(k)/adjExp(k)): this is the multiplicative discrepancy between observed and expected. ## adddiff columns show additive discrepancy: actual_CI minus exp_CI, in percentage points of the k=2 CI expected width. This is the vertical distance between the observed and expected curves on the normalised plot; +25 means the observed curve sits 25 points (a quarter of the k=2 width) above expected. Assessed in in_addband columns. ## informative = whether the position counts towards assessment. TRUE for k≥3; FALSE for k=1 (a single unpooled group) and k=2 (the anchor - both positions forced to 100). ## in_ratioband columns show relative criterion: TRUE if ratio lies within [1/tau, tau] = [0.80, 1.25] (observed within ±25% of expected, multiplicatively), FALSE if outside, NA if non-informative. ## in_addband columns show absolute criterion: TRUE if |gap_pp| ≤ delta = 25 (observed within 25 percentage points = a quarter of the k=2 expected width), FALSE if outside, NA if non-informative. ## print(bandlistNOsys, row.names = FALSE)## $Tonk##  k actualCI_NoW actualCI_W expCI ratiodiff_NoW ratiodiff_W adddiff_NoW adddiff_W informative in_ratioband_NoW in_ratioband_W in_addband_NoW in_addband_W##  1        100.1      100.0 142.3         -29.7       -29.7       -42.2     